VALUES ((SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R25BK80000101'), 'QA010', '모바일 화면은 앱입니까, 웹입니까?', '반응형 웹으로 구현하여 별도 설치 없이 모바일 브라우저에서 같은 기능을 씁니다.', (SELECT RQT_MTTR_SN FROM TB_RQT_MTTR WHERE PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R25BK80000101') AND RQT_MTTR_NO = 'SFR-004'), '2023-0112', TO_DATE('2025-03-22 15:00', 'YYYY-MM-DD HH24:MI'));
