INSERT INTO TB_QSTN_ANS (PBANC_SN, QSTN_ANS_SE_CD, QSTN_CN, ANS_CN, RQT_MTTR_SN, WRTR_ID, WRT_DT)
VALUES ((SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R25BK80000303'), 'QA010', '기존 시스템 사용자 권한을 그대로 옮길 수 있습니까?', '권한 매핑표를 만들어 시험 이관 때 사용자별로 대조하고, 차이는 발주기관 확인 후 반영합니다.', (SELECT RQT_MTTR_SN FROM TB_RQT_MTTR WHERE PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R25BK80000303') AND RQT_MTTR_NO = 'SFR-001'), '2025-0215', TO_DATE('2025-03-08 15:00', 'YYYY-MM-DD HH24:MI'));
INSERT INTO TB_QSTN_ANS (PBANC_SN, QSTN_ANS_SE_CD, QSTN_CN, ANS_CN, RQT_MTTR_SN, WRTR_ID, WRT_DT)
VALUES ((SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R25BK80000303'), 'QA010', '모바일 화면은 앱입니까, 웹입니까?', '반응형 웹으로 구현하여 별도 설치 없이 모바일 브라우저에서 같은 기능을 씁니다.', (SELECT RQT_MTTR_SN FROM TB_RQT_MTTR WHERE PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R25BK80000303') AND RQT_MTTR_NO = 'SFR-004'), '2022-0213', TO_DATE('2025-03-08 15:00', 'YYYY-MM-DD HH24:MI'));
