INSERT INTO TB_QSTN_ANS (PBANC_SN, QSTN_ANS_SE_CD, QSTN_CN, ANS_CN, RQT_MTTR_SN, WRTR_ID, WRT_DT)
VALUES ((SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R24BK80001010'), 'QA010', '기존 시스템 사용자 권한을 그대로 옮길 수 있습니까?', '권한 매핑표를 만들어 시험 이관 때 사용자별로 대조하고, 차이는 발주기관 확인 후 반영합니다.', (SELECT RQT_MTTR_SN FROM TB_RQT_MTTR WHERE PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R24BK80001010') AND RQT_MTTR_NO = 'SFR-001'), '2025-0426', TO_DATE('2024-11-16 15:00', 'YYYY-MM-DD HH24:MI'));
INSERT INTO TB_QSTN_ANS (PBANC_SN, QSTN_ANS_SE_CD, QSTN_CN, ANS_CN, RQT_MTTR_SN, WRTR_ID, WRT_DT)
VALUES ((SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R24BK80001010'), 'QA010', '모바일 화면은 앱입니까, 웹입니까?', '반응형 웹으로 구현하여 별도 설치 없이 모바일 브라우저에서 같은 기능을 씁니다.', (SELECT RQT_MTTR_SN FROM TB_RQT_MTTR WHERE PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R24BK80001010') AND RQT_MTTR_NO = 'SFR-004'), '2023-0421', TO_DATE('2024-11-16 15:00', 'YYYY-MM-DD HH24:MI'));
INSERT INTO TB_QSTN_ANS (PBANC_SN, QSTN_ANS_SE_CD, QSTN_CN, ANS_CN, RQT_MTTR_SN, WRTR_ID, WRT_DT)
VALUES ((SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R24BK80001010'), 'QA010', '행정정보 공동이용 연계 승인은 누가 받습니까?', '승인 신청은 발주기관이 하고, 우리는 연계 규격서와 시험 결과를 준비해 지원합니다.', (SELECT RQT_MTTR_SN FROM TB_RQT_MTTR WHERE PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R24BK80001010') AND RQT_MTTR_NO = 'INR-001'), '2022-0424', TO_DATE('2024-11-16 15:00', 'YYYY-MM-DD HH24:MI'));
INSERT INTO TB_QSTN_ANS (PBANC_SN, QSTN_ANS_SE_CD, QSTN_CN, ANS_CN, RQT_MTTR_SN, WRTR_ID, WRT_DT)
VALUES ((SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R24BK80001010'), 'QA010', '개인정보 암호화 범위는 어디까지입니까?', '주민등록번호·계좌번호 등 고유식별정보는 저장 시 암호화하고 전 구간 TLS를 적용합니다.', (SELECT RQT_MTTR_SN FROM TB_RQT_MTTR WHERE PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R24BK80001010') AND RQT_MTTR_NO = 'SER-001'), '2025-0423', TO_DATE('2024-11-16 15:00', 'YYYY-MM-DD HH24:MI'));
INSERT INTO TB_QSTN_ANS (PBANC_SN, QSTN_ANS_SE_CD, QSTN_CN, ANS_CN, WRTR_ID, WRT_DT)
VALUES ((SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R24BK80001010'), 'QA020', '유사 사업 경험에서 가장 어려웠던 점은 무엇이었습니까?', '기관 간 연계 일정이 늦어진 점이었고, 연계 시험 환경을 먼저 마련해 일정을 지켰습니다.', '2024-0402', TO_DATE('2024-11-16 15:00', 'YYYY-MM-DD HH24:MI'));
INSERT INTO TB_QSTN_ANS (PBANC_SN, QSTN_ANS_SE_CD, QSTN_CN, ANS_CN, WRTR_ID, WRT_DT)
